/*
 * DELETE THE SIGNED-IN PERSON'S ACCOUNT AND EVERYTHING ABOUT THEM (TASK-L185 §4).
 *
 * The rows come from `shared/Rows about`, the same plan the export reads, and
 * are removed in its `order`: every collection before anything it hangs off,
 * the learner profile after all of them, the account last.
 *
 * THERE IS NO TRANSACTION (NodeGX HLT-016 (b) is ruled out), so the ORDER is
 * the safety property, as in finishStep (L178). A crash part-way leaves an
 * account that can still sign in and press delete again, and the second run
 * finds whatever is left and finishes. A crash can never leave rows about a
 * person with no account left to delete them from, because the account is the
 * last thing to go, and its sessions go just before it.
 *
 * NOTHING IS KEPT. The product keeps confusion signals unlinked (for its
 * curriculum loop) and the credit ledger (accounting law); this template has
 * neither a loop nor a ledger, so both reasons are absent and those rows go.
 * The notice and the settings page say so before the button is pressed.
 *
 * `confirm` must be the word DELETE: the page asks the person to type it, and
 * the server checks it too, so a stray call cannot erase somebody.
 */
if (Inputs.userId !== undefined && Inputs.rows !== undefined && Inputs.order !== undefined && Inputs.confirm !== undefined) {
  (async () => {
    try {
      const userId = String(Inputs.userId || '');
      if (!userId) throw new Error('no account');
      if (String(Inputs.confirm) !== 'DELETE') throw new Error('not confirmed');
      const R = Noodl.Records;
      const del = (c, r) => R.delete(r.objectId, { className: c });
      const rows = Inputs.rows || {};
      const counts = {};
      for (const c of Inputs.order || []) {
        const list = rows[c] || [];
        for (const r of list) await del(c, r);
        counts[c] = list.length;
      }

      // ── The account. Role memberships, sign-in identities and email tokens
      //    first, then sessions, then the account itself.
      const q = (c, where) => R.query(c, where, { limit: 1000, plain: true });
      const roleList = await q('_Role', {});
      for (const role of roleList) {
        await R.removeRelation({ className: '_Role', recordId: role.objectId, key: 'users', targetRecordId: userId, targetClassName: '_User' });
      }
      for (const c of ['_UserIdentity', '_EmailToken', '_Session']) {
        const list = await q(c, { userId: { equalTo: userId } });
        for (const r of list) await del(c, r);
        counts[c] = list.length;
      }
      await R.delete(userId, { className: '_User' });
      counts._User = 1;

      console.log('[dbt:deleteMine] done user=' + userId + ' rows=' + Object.values(counts).reduce((a, b) => a + b, 0));
      Outputs.deleted = true;
      Outputs.done();
    } catch (e) {
      Outputs.error = String((e && e.message) || e);
      console.error('[dbt:deleteMine] stopped: ' + Outputs.error + ' user=' + String(Inputs.userId || '-'));
      Outputs.failed();
    }
  })();
}
